SHOW CREATE TABLE branch_orders.orders;
SELECT c.id AS customer_id,c.name,o.id AS order_id,CAST(o.amount AS CHAR) AS amount FROM branch_orders.customers c JOIN branch_orders.orders o ON o.customer_id=c.id ORDER BY o.id;
